import importlib,json
from pathlib import Path
results={}
for name,load,status in [('extension','load_amd_extension','extension_status'),('ck_extension','load_ck_extension','extension_status'),('mask_bias','load','manifest'),('pair_fusions','load','manifest'),('ck_attention','load_extension','extension_status'),('lt_bmm','load_extension','extension_status')]:
 m=importlib.import_module('fireprot.backends.amd.'+name)
 obj=getattr(m,load)();s=getattr(m,status)();b=s.get('build') or {}
 results[name]={'loaded':obj is not None,'error':s.get('error'),'cache_hit':b.get('cache_hit'),'directory':b.get('directory'),'library':b.get('library'),'library_sha256':b.get('library_sha256')}
 Path('/tmp/fireprot-installed-builds.json').write_text(json.dumps(results,indent=2)+'\n')
 assert obj is not None,(name,s)
 assert b.get('cache_hit') is False,(name,b.get('cache_hit'))
print(json.dumps(results,indent=2))
